#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define D 768
#define H 12
#define L 12
#define V 50257
#define N 1024
#define F 3072
#define R 64
float*C,*W[L][12],*lb,*lg,*we,*pe,*x,*kc[L],*vc[L];
int TR=0;
void ln(float*o,float*x,float*g,float*b){float m=0,v=0;
 for(int j=0;j<D;j++)m+=x[j];m/=D;
 for(int j=0;j<D;j++){float d=x[j]-m;v+=d*d;}
 v=sqrtf(v/D+1e-5f);for(int j=0;j<D;j++)o[j]=(x[j]-m)/v*g[j]+b[j];}
void mm(float*o,float*x,float*w,float*b,int d,int k){
 for(int j=0;j<d;j++){float s=b?b[j]:0;
  if(TR)for(int p=0;p<k;p++)s+=x[p]*w[j*k+p];
  else for(int p=0;p<k;p++)s+=x[p]*w[p*d+j];o[j]=s;}}
void fwd(int p){float xn[D],q[3*D],a[D],pr[D],x2[D],h[F],h2[D],sc[N];
 for(int l=0;l<L;l++){
  ln(xn,x+p*D,W[l][5],W[l][4]);mm(q,xn,W[l][1],W[l][0],3*D,D);
  memcpy(kc[l]+p*D,q+D,D*4);memcpy(vc[l]+p*D,q+2*D,D*4);
  for(int hh=0;hh<H;hh++){float mx=-1e9f;
   for(int j=0;j<=p;j++){float s=0;for(int d=0;d<R;d++)s+=q[hh*R+d]*kc[l][j*D+hh*R+d];
    s*=.125f;sc[j]=s;if(s>mx)mx=s;}
   float sm=0;for(int j=0;j<=p;j++){sc[j]=expf(sc[j]-mx);sm+=sc[j];}
   for(int d=0;d<R;d++){float s=0;for(int j=0;j<=p;j++)s+=sc[j]/sm*vc[l][j*D+hh*R+d];a[hh*R+d]=s;}}
  mm(pr,a,W[l][3],W[l][2],D,D);for(int j=0;j<D;j++)x[p*D+j]+=pr[j];
  ln(x2,x+p*D,W[l][7],W[l][6]);mm(h,x2,W[l][9],W[l][8],F,D);
  for(int j=0;j<F;j++){float t=h[j];h[j]=.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
  mm(h2,h,W[l][11],W[l][10],D,F);for(int j=0;j<D;j++)x[p*D+j]+=h2[j];}}
// GPT-2 load_params order: ln_1/g,b, c_attn/w,b, c_proj/w,b, ln_2/g,b, mlp_c_fc/w,b, mlp_c_proj/w,b
// W indices: 4=ln1_b, 5=ln1_g, 0=c_attn_b, 1=c_attn_w, 2=c_proj_b, 3=c_proj_w, 6=ln2_b, 7=ln2_g, 8=mlp_fc_b, 9=mlp_fc_w, 10=mlp_proj_b, 11=mlp_proj_w
void setup(int global,int tr){
 TR=tr;float*p=C;
 if(global){we=p;p+=V*D;pe=p;p+=N*D;}
 for(int l=0;l<L;l++){
  W[l][5]=p;p+=D;W[l][4]=p;p+=D;   // ln_1/g, ln_1/b
  W[l][1]=p;p+=3*D*D;W[l][0]=p;p+=3*D; // c_attn/w, c_attn/b
  W[l][3]=p;p+=D*D;W[l][2]=p;p+=D;     // c_proj/w, c_proj/b
  W[l][7]=p;p+=D;W[l][6]=p;p+=D;       // ln_2/g, ln_2/b
  W[l][9]=p;p+=F*D;W[l][8]=p;p+=F;     // mlp_c_fc/w, mlp_c_fc/b
  W[l][11]=p;p+=F*D;W[l][10]=p;p+=D;   // mlp_c_proj/w, mlp_c_proj/b
 }
 if(global){lg=p;p+=D;lb=p;p+=D;}
 else{lg=p;p+=D;lb=p;p+=D;we=p;p+=V*D;pe=p;}
}
int main(){C=malloc(497759232);FILE*f=fopen("/app/gpt2-124M.ckpt","rb");fread(C,4,124439808,f);fclose(f);
 for(int g=0;g<2;g++)for(int tr=0;tr<2;tr++){
  setup(g,tr);
  x=calloc(N*D,4);for(int l=0;l<L;l++){kc[l]=calloc(N*D,4);vc[l]=calloc(N*D,4);}
  for(int j=0;j<D;j++)x[j]=we[464*D+j]+pe[j];
