  printf("g=%d tr=%d:",g,tr);
  for(int t=0;t<5;t++){int best=0;float mx=-1e9f;for(int j=0;j<V;j++)if(scores[j]>mx){mx=scores[j];best=j;}printf(" %d(%.1f)",best,mx);scores[best]=-1e9f;}
  printf("\n");
  free(x);for(int l=0;l<L;l++){free(kc[l]);free(vc[l]);}
 }
 return 0;}
